content.text:
{
  "primary_meaning": "The Messiah/Christ as the singular promised offspring who fulfills the covenant promises made to the woman, Abraham, and David",
  "primary_basis": [
    "Genesis 3:15",
    "Genesis 12:7",
    "Genesis 22:18",
    "2 Samuel 7:12-13",
    "Galatians 3:16",
    "Romans 1:3"
  ],
  "alternatives": [
    {
      "meaning": "The word/gospel of God sown into human hearts",
      "basis": [
        "Matthew 13:18-23",
        "Mark 4:14",
        "Luke 8:11"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Physical or spiritual descendants/offspring in general",
      "basis": [
        "Genesis 15:5",
        "Genesis 13:16",
        "Romans 9:7-8",
        "Galatians 3:29"
      ],
      "prominence": "dominant"
    },
    {
      "meaning": "Christ (or the believer) dying like a grain of wheat in order to produce fruit",
      "basis": [
        "John 12:24",
        "1 Corinthians 15:36-38"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The righteous remnant or the church itself as the product of divine sowing",
      "basis": [
        "Isaiah 6:13",
        "Matthew 13:24-30",
        "1 Corinthians 3:6-9"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "Multiple context-dependent meanings are firmly established in Christian biblical interpretation; the messianic/covenantal sense is the most theologically central for the capitalized or absolute use of 'Seed,' while the parable-of-the-sower sense is equally common in teaching on the gospel."
}
